from html.parser import HTMLParser
from urllib.parse import urljoin,urlsplit,urldefrag
import pathlib,json,collections
p=pathlib.Path('pilot/collection/parts/000001')
a=lambda n:[json.loads(l) for l in (p/(n+'.jsonl')).read_text().splitlines()]
ev=a('evidence')
class P(HTMLParser):
 def __init__(self,s):
  super().__init__();self.ids=set();self.href=[];self.scripts=[];self.feed(s)
 def handle_starttag(self,t,attrs):
  d=dict(attrs)
  if d.get('id'):self.ids.add(d['id'])
  if t=='a' and d.get('href'):self.href.append(d['href'])
  if t=='script':self.scripts.append(d.get('type'))
ps={}
for i in a('inventory'):
 c=next(e for e in ev if e['itemId']==i['itemId'] and e['kind']=='content')
 ps[i['uri']]=P((p/c['artifact']).read_text())
for u,x in ps.items():
 print(u,'scripts',x.scripts)
 for h in set(x.href):
  v,f=urldefrag(urljoin(u,h))
  if v in ps and f and f not in ps[v].ids:print('MISSING',h,v,f)
  if 'content-search' in h:print('AUDIT',h)
s=json.loads(pathlib.Path('pilot/continued/source.json').read_text())
print('Exclusions',len(s['exclusions']),len({x['locator'] for x in s['exclusions']}))
